<?=$logo?>" alt=""><?php endif;?><div><b>LIBERTY CLASS AND CAREER</b><small>Computer Based Test</small></div></header><section class="hero"><h1>Well done, <?=e($studentName)?>!</h1><div><?=e($attempt['title'])?></div><div class="score"><?=e($attempt['obtained_marks'])?> <small>/ <?=e($attempt['full_marks'])?> · <?=e($attempt['accuracy'])?>% accuracy</small></div></section><table class="stats"><tr><td><b><?=e($attempt['obtained_marks'])?></b>Score</td><td><b><?=e($attempt['correct_count'])?></b>Correct</td><td><b><?=e($attempt['wrong_count'])?></b>Wrong</td><td><b><?=e($attempt['skipped_count'])?></b>Skipped</td><td><b><?=e($attempt['accuracy'])?>%</b>Accuracy</td></tr></table><h2 class="section-title">Detailed Answer Analysis</h2><?php foreach($review as $q):$state=$q['is_correct']===null?'skipped':((int)$q['is_correct']===1?'correct':'wrong');?><article class="question"><div class="question-head">QUESTION <?=e($q['position'])?> OF <?=count($review)?><span class="state <?=$state?>"><?=e($state==='wrong'?'Incorrect':ucfirst($state))?> · <?=e((float)$q['mark_obtained']>0?'+':'')?><?=e($q['mark_obtained']??'0.00')?></span></div><h3><?=e($q['position'])?>. <?=e($q['question_text'])?></h3><?php $questionImage=$mediaData($q['image_path']??null);if($questionImage):?><img class="media" src="<?=$questionImage?>" alt=""><?php endif;?><?php if($q['type']==='typed'):?><div class="answers"><span>Your answer: <b><?=e($q['typed_answer']?:'Not answered')?></b></span><span>Correct answer: <b><?=e(implode(', ',json_decode($q['accepted_text']?:'[]',true)?:[]))?></b></span></div><?php else:$selected=array_filter(explode(',',(string)$q['selected']));foreach($q['options'] as $o):$chosen=in_array((string)$o['id'],$selected,true);?><div class="option <?=$chosen?'chosen ':''?><?=$o['is_correct']?'right':''?>"><b><?=e($o['option_key'])?></b><?=e($o['option_text'])?><?php if($o['is_correct']&&$chosen):?><em>Your answer · Correct</em><?php elseif($o['is_correct']):?><em>Correct answer</em><?php elseif($chosen):?><em>Your answer</em><?php endif;?><?php $optionImage=$mediaData($o['image_path']??null);if($optionImage):?><img class="media" src="<?=$optionImage?>" alt=""><?php endif;?></div><?php endforeach;?><div class="answers"><span>Your answer: <b><?=e($selected?implode(', ',array_map(static function($id)use($q){foreach($q['options'] as $option)if((string)$option['id']===(string)$id)return $option['option_key'];return '';},$selected)):'Not answered')?></b></span><span>Correct answer: <b><?=e(implode(', ',array_map(static fn($option)=>$option['option_key'],array_filter($q['options'],static fn($option)=>(int)$option['is_correct']===1))))?></b></span></div><?php endif;?></article><?php endforeach;?><footer>End of Answer Analysis · Generated by Liberty Class and Career (CBT)</footer></body></html>
